import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs["target_positions"].copy()
    events = inputs["position_events"].copy()

    # 1. Distinct by batch_seq (duplicate deliveries of the same event collapse to one)
    events = events.drop_duplicates(subset="batch_seq", keep="first")

    # Build lookup of current target rows by key
    target_map = {}
    for _, row in target.iterrows():
        key = (row["account_id"], row["symbol"])
        target_map[key] = {
            "qty": row["qty"],
            "price": row["price"],
            "row_version": row["row_version"],
        }

    new_rows = []
    closed_rows = []
    processed_keys = set()

    if not events.empty:
        grouped = events.groupby(["account_id", "symbol"], sort=False)
    else:
        grouped = []

    for key, grp in (grouped if not events.empty else []):
        account_id, symbol = key
        processed_keys.add(key)

        tgt = target_map.get(key)
        guard_version = tgt["row_version"] if tgt is not None else None

        grp_sorted = grp.sort_values(["row_version", "batch_seq"], kind="mergesort")

        if guard_version is not None:
            grp_sorted = grp_sorted[grp_sorted["row_version"] > guard_version]

        state = dict(tgt) if tgt is not None else None
        applied_any = False
        last_closed = False
        last_closed_version = None

        for _, ev in grp_sorted.iterrows():
            op = ev["op"]
            qty = ev["qty"]
            price = ev["price"]
            rv = ev["row_version"]

            if op == "D":
                if state is not None:
                    state = None
                    applied_any = True
                    last_closed = True
                    last_closed_version = rv
                # else: no-op, no state change

            elif op in ("I", "U"):
                if pd.notna(qty) and qty == 0:
                    if state is not None:
                        state = None
                        applied_any = True
                        last_closed = True
                        last_closed_version = rv
                    # else: no-op
                else:
                    if state is not None:
                        if op == "U" and pd.isna(price):
                            new_price = state["price"]
                        else:
                            new_price = price
                        state = {"qty": qty, "price": new_price, "row_version": rv}
                        applied_any = True
                        last_closed = False
                    else:
                        state = {"qty": qty, "price": price, "row_version": rv}
                        applied_any = True
                        last_closed = False
            # unknown ops are ignored (not specified)

        if applied_any and last_closed:
            closed_rows.append(
                {
                    "account_id": account_id,
                    "symbol": symbol,
                    "closed_version": last_closed_version,
                }
            )
        else:
            if state is not None:
                new_rows.append(
                    {
                        "account_id": account_id,
                        "symbol": symbol,
                        "qty": state["qty"],
                        "price": state["price"],
                        "row_version": state["row_version"],
                    }
                )

    # Untouched keys: carry forward as-is
    for key, tgt in target_map.items():
        if key not in processed_keys:
            new_rows.append(
                {
                    "account_id": key[0],
                    "symbol": key[1],
                    "qty": tgt["qty"],
                    "price": tgt["price"],
                    "row_version": tgt["row_version"],
                }
            )

    new_positions = pd.DataFrame(
        new_rows, columns=["account_id", "symbol", "qty", "price", "row_version"]
    )
    closed_positions = pd.DataFrame(
        closed_rows, columns=["account_id", "symbol", "closed_version"]
    )

    if not new_positions.empty:
        new_positions["account_id"] = new_positions["account_id"].astype("int64")
        new_positions["qty"] = new_positions["qty"].astype("int64")
        new_positions["price"] = new_positions["price"].astype("float64")
        new_positions["row_version"] = new_positions["row_version"].astype("int64")
    else:
        new_positions = pd.DataFrame(
            {
                "account_id": pd.Series(dtype="int64"),
                "symbol": pd.Series(dtype="object"),
                "qty": pd.Series(dtype="int64"),
                "price": pd.Series(dtype="float64"),
                "row_version": pd.Series(dtype="int64"),
            }
        )

    if not closed_positions.empty:
        closed_positions["account_id"] = closed_positions["account_id"].astype("int64")
        closed_positions["closed_version"] = closed_positions["closed_version"].astype(
            "int64"
        )
    else:
        closed_positions = pd.DataFrame(
            {
                "account_id": pd.Series(dtype="int64"),
                "symbol": pd.Series(dtype="object"),
                "closed_version": pd.Series(dtype="int64"),
            }
        )

    return {"new_positions": new_positions, "closed_positions": closed_positions}
